using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using RagnarokCompanion.Models;
namespace RagnarokCompanion.Services;
public sealed record BuildSyncState(string Data,DateTimeOffset Updated,DateTimeOffset RetryAfter,int Failures);
public sealed record CatalogPage(List<CommunityBuild> Builds,string? Cursor,bool HasMore);
public sealed record CachedCatalogPage(List<string> Ids,string? Cursor,bool HasMore);
public sealed partial class BuildRepository
{
 public bool HasApprovedPublication(string uid,PlayerBuild build){if(uid.Length==0)return false;EnsureSyncTables();using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT payload FROM community_summaries WHERE class_id=$class AND stage=$stage UNION ALL SELECT payload FROM community_build_cache WHERE class_id=$class AND stage=$stage";c.Parameters.AddWithValue("$class",build.ClassId);c.Parameters.AddWithValue("$stage",build.Stage);using var r=c.ExecuteReader();while(r.Read()){var row=JsonSerializer.Deserialize<CommunityBuild>(r.GetString(0));if(row?.Status=="approved"&&row.OwnerUid==uid&&row.Build.Id==build.Id)return true;}return false;}
 public List<CommunityBuild> SearchCommunity(string cls,string stage,string purpose,string query){EnsureSyncTables();string term=MvpSearchCoordinator.Normalize(query.Trim());using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT payload FROM community_summaries WHERE class_id=$class AND stage=$stage AND purpose=$purpose";c.Parameters.AddWithValue("$class",cls);c.Parameters.AddWithValue("$stage",stage);c.Parameters.AddWithValue("$purpose",purpose);using var r=c.ExecuteReader();var result=new List<CommunityBuild>();while(r.Read()&&result.Count<20){var row=JsonSerializer.Deserialize<CommunityBuild>(r.GetString(0));if(row!=null&&MvpSearchCoordinator.Normalize(row.Build.Title+" "+row.AuthorName).Contains(term))result.Add(Hydrate(row));}return result;}
 bool syncTablesReady;void EnsureSyncTables(){if(syncTablesReady)return;using var db=Open();using var c=db.CreateCommand();c.CommandText="CREATE TABLE IF NOT EXISTS community_summaries(id TEXT PRIMARY KEY,class_id TEXT,stage TEXT,purpose TEXT,payload TEXT NOT NULL);CREATE TABLE IF NOT EXISTS community_contents(id TEXT PRIMARY KEY,version INTEGER NOT NULL,payload TEXT NOT NULL);CREATE TABLE IF NOT EXISTS build_sync_state(key TEXT PRIMARY KEY,data TEXT NOT NULL,updated TEXT NOT NULL,retry_after TEXT NOT NULL,failures INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS build_sync_history(at TEXT NOT NULL,key TEXT NOT NULL,outcome TEXT NOT NULL);";c.ExecuteNonQuery();syncTablesReady=true;}
 public BuildSyncState? SyncState(string key){EnsureSyncTables();using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT data,updated,retry_after,failures FROM build_sync_state WHERE key=$key";c.Parameters.AddWithValue("$key",key);using var r=c.ExecuteReader();return r.Read()?new(r.GetString(0),DateTimeOffset.Parse(r.GetString(1)),DateTimeOffset.Parse(r.GetString(2)),r.GetInt32(3)):null;}
 public void SaveSyncState(string key,BuildSyncState state,string outcome){EnsureSyncTables();using var db=Open();using var tx=db.BeginTransaction();using var c=db.CreateCommand();c.Transaction=tx;c.CommandText="INSERT OR REPLACE INTO build_sync_state VALUES($key,$data,$updated,$retry,$failures);INSERT INTO build_sync_history VALUES($at,$key,$outcome);DELETE FROM build_sync_history WHERE rowid NOT IN (SELECT rowid FROM build_sync_history ORDER BY rowid DESC LIMIT 500)";c.Parameters.AddWithValue("$key",key);c.Parameters.AddWithValue("$data",state.Data);c.Parameters.AddWithValue("$updated",state.Updated.ToString("O"));c.Parameters.AddWithValue("$retry",state.RetryAfter.ToString("O"));c.Parameters.AddWithValue("$failures",state.Failures);c.Parameters.AddWithValue("$at",DateTimeOffset.UtcNow.ToString("O"));c.Parameters.AddWithValue("$outcome",outcome);c.ExecuteNonQuery();tx.Commit();}
 public void StoreCommunity(IEnumerable<CommunityBuild> builds){EnsureSyncTables();using var db=Open();using var tx=db.BeginTransaction();foreach(var row in builds){var b=row.Build;var summary=row with{Build=new(){Id=b.Id,Title=b.Title,ClassId=b.ClassId,Stage=b.Stage,Purpose=b.Purpose,UpdatedUtc=b.UpdatedUtc,Equipment=new(),Stats=new(),Notes=""},HasContent=false};using var c=db.CreateCommand();c.Transaction=tx;c.CommandText="INSERT OR REPLACE INTO community_summaries VALUES($id,$class,$stage,$purpose,$payload)";c.Parameters.AddWithValue("$id",row.Id);c.Parameters.AddWithValue("$class",b.ClassId);c.Parameters.AddWithValue("$stage",b.Stage);c.Parameters.AddWithValue("$purpose",b.Purpose);c.Parameters.AddWithValue("$payload",JsonSerializer.Serialize(summary));c.ExecuteNonQuery();if(row.HasContent){c.CommandText="INSERT INTO community_contents VALUES($id,$version,$body) ON CONFLICT(id) DO UPDATE SET version=$version,payload=$body WHERE excluded.version >= community_contents.version";c.Parameters.AddWithValue("$version",row.Version);c.Parameters.AddWithValue("$body",JsonSerializer.Serialize(b));c.ExecuteNonQuery();}}tx.Commit();}
 public void ReconcileCommunity(string cls,string stage,string purpose,IEnumerable<CommunityBuild> complete){EnsureSyncTables();var ids=complete.Select(b=>b.Id).Distinct().ToArray();using var db=Open();using var tx=db.BeginTransaction();using var c=db.CreateCommand();c.Transaction=tx;c.Parameters.AddWithValue("$class",cls);c.Parameters.AddWithValue("$stage",stage);c.Parameters.AddWithValue("$purpose",purpose);for(int i=0;i<ids.Length;i++)c.Parameters.AddWithValue("$id"+i,ids[i]);string scope="class_id=$class AND stage=$stage AND purpose=$purpose"+(ids.Length==0?"":" AND id NOT IN ("+string.Join(",",ids.Select((_,i)=>"$id"+i))+")");c.CommandText="DELETE FROM community_contents WHERE id IN (SELECT id FROM community_summaries WHERE "+scope+" UNION SELECT id FROM community_build_cache WHERE "+scope+");DELETE FROM community_summaries WHERE "+scope+";DELETE FROM community_build_cache WHERE "+scope;c.ExecuteNonQuery();tx.Commit();}
 public CommunityBuild? CommunityById(string id){EnsureSyncTables();using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT payload FROM community_summaries WHERE id=$id";c.Parameters.AddWithValue("$id",id);if(c.ExecuteScalar() is string json&&JsonSerializer.Deserialize<CommunityBuild>(json) is {} row)return Hydrate(row);c.CommandText="SELECT payload FROM community_build_cache WHERE id=$id";return c.ExecuteScalar() is string old?JsonSerializer.Deserialize<CommunityBuild>(old):null;}
 public CommunityBuild Hydrate(CommunityBuild row,bool allowOlder=false){EnsureSyncTables();using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT version,payload FROM community_contents WHERE id=$id";c.Parameters.AddWithValue("$id",row.Id);using var r=c.ExecuteReader();if(r.Read()&&(allowOlder||r.GetInt64(0)==row.Version))return row with{Build=JsonSerializer.Deserialize<PlayerBuild>(r.GetString(1))!,HasContent=true,Version=r.GetInt64(0)};return row;}
 List<CommunityBuild> ReadCommunity(string classId,string stage,string purpose){EnsureSyncTables();using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT payload FROM community_summaries WHERE class_id=$class AND stage=$stage AND purpose=$purpose LIMIT 20";c.Parameters.AddWithValue("$class",classId);c.Parameters.AddWithValue("$stage",stage);c.Parameters.AddWithValue("$purpose",purpose);var rows=new List<CommunityBuild>();using(var r=c.ExecuteReader())while(r.Read())if(JsonSerializer.Deserialize<CommunityBuild>(r.GetString(0)) is {} row)rows.Add(Hydrate(row));if(rows.Count>0)return rows;c.CommandText="SELECT payload FROM community_build_cache WHERE class_id=$class AND stage=$stage AND purpose=$purpose LIMIT 20";using var legacy=c.ExecuteReader();while(legacy.Read())if(JsonSerializer.Deserialize<CommunityBuild>(legacy.GetString(0)) is {} row)rows.Add(row);return rows;}
}
